    RETURNING id INTO v_owner_id;

    IF v_owner_id IS NULL THEN
        SELECT id INTO v_owner_id FROM owners WHERE email = "nolfonzo@gmail.com" LIMIT 1;
    END IF;

    INSERT INTO devices (node_id, display_name, owner_id)
    VALUES (2697689064, "Heltec Wattmeter (Pi4)", v_owner_id)
    ON CONFLICT (node_id) DO UPDATE SET owner_id = v_owner_id, display_name = "Heltec Wattmeter (Pi4)"
    RETURNING id INTO v_device_id;

    IF v_device_id IS NULL THEN
        SELECT id INTO v_device_id FROM devices WHERE node_id = 2697689064 LIMIT 1;
    END IF;

    INSERT INTO bus_pins (device_id, pin_index)
